PARAMS = ['R0','kout','Imax','IC50','gam']
def predict(df, p):
    def solve_one(dose, ts):
        ts = np.asarray(ts, float)
        kin = p['R0']*p['kout']
        def f(t, y):
            C = pk_conc(dose, t)
            Cg = C**p['gam']
            return [kin*(1 - p['Imax']*Cg/(p['IC50']**p['gam'] + Cg)) - p['kout']*y[0]]
        sol = solve_ivp(f, (0, ts.max()), [p['R0']], t_eval=ts, rtol=1e-8, atol=1e-8)
        return sol.y[0]
    return per_dose(df, solve_one)

